<?php
require __DIR__.'/../includes/bootstrap.php';$u=require_role(['admin']);$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$code=strtoupper(trim($_POST['code']??''));$type=$_POST['discount_type']??'percent';$value=(float)($_POST['discount_value']??0);$min=(float)($_POST['min_purchase']??0);
 if(!preg_match('/^[A-Z0-9_-]{3,40}$/',$code)||!in_array($type,['percent','fixed'],true)||$value<=0||$min<0||($type==='percent'&&$value>100))$notice='Please enter valid discount details.';
 else{try{$q=db()->prepare("INSERT INTO discounts(code,discount_type,discount_value,min_purchase,starts_at,ends_at,usage_limit) VALUES(?,?,?,?,?,?,?)");$q->execute([$code,$type,$value,$min,$_POST['starts_at']?:null,$_POST['ends_at']?:null,$_POST['usage_limit']!==''?(int)$_POST['usage_limit']:null]);$notice='Discount created.';}catch(Throwable $e){$notice='Could not create discount. Check that the code is unique.';}}}
$rows=db()->query("SELECT * FROM discounts ORDER BY id DESC")->fetchAll();$pageTitle='Discounts';include __DIR__.'/../includes/header.php';?>
<h1>Discounts / coupons</h1><?php if($notice):?><div class="alert"><?=e($notice)?></div><?php endif?>
<form method="post" class="panel"><?=csrf_field()?><label>Coupon code<input name="code" required></label><label>Type<select name="discount_type"><option value="percent">Percentage</option><option value="fixed">Fixed amount</option></select></label><label>Value<input type="number" step=".01" min=".01" name="discount_value" required></label><label>Minimum purchase<input type="number" step=".01" min="0" name="min_purchase" value="0"></label><label>Starts<input type="datetime-local" name="starts_at"></label><label>Ends<input type="datetime-local" name="ends_at"></label><label>Usage limit<input type="number" min="1" name="usage_limit"></label><button class="btn">Create discount</button></form>
<div class="table-wrap"><table><tr><th>Code</th><th>Type</th><th>Value</th><th>Used</th><th>Active</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['discount_type'])?></td><td><?=e($r['discount_value'])?></td><td><?=e($r['used_count'])?></td><td><?=e($r['is_active'])?></td></tr><?php endforeach?></table></div>
<?php include __DIR__.'/../includes/footer.php';?>